const headers = $json.headers || {};
const body = $json.body || $json;

const expectedToken = $env.AUTOFIX_RUNNER_WEBHOOK_TOKEN || '';
const receivedToken = headers['x-autofix-runner-token'] || '';

function timingSafeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

const authValid = expectedToken.length > 0 && timingSafeEqual(receivedToken, expectedToken);

const errors = [];
const incidentId = body.incidentId;
const jiraKey = body.jiraKey;
const fingerprint = body.fingerprint;
const branchName = body.branchName;

if (!(Number.isInteger(incidentId) && incidentId > 0)) {
  errors.push('incidentId must be a positive integer');
}
if (typeof jiraKey !== 'string' || !/^AUTO-[0-9]+$/.test(jiraKey)) {
  errors.push('jiraKey must match ^AUTO-[0-9]+$');
}
if (typeof fingerprint !== 'string' || !/^[0-9a-f]{64}$/.test(fingerprint)) {
  errors.push('fingerprint must be exactly 64 hex characters');
}
if (typeof branchName !== 'string' || (typeof jiraKey === 'string' && branchName !== ('autofix/' + jiraKey))) {
  errors.push('branchName must equal autofix/<jiraKey>');
}

return {
  json: {
    authValid,
    fieldsValid: errors.length === 0,
    errors,
    incidentId,
    jiraKey,
    fingerprint,
    branchName,
  },
};

const item = $json;
if (item.error) {
  const message = typeof item.error === 'string' ? item.error : (item.error.message || JSON.stringify(item.error));
  const isNotFound = /404|does not exist|no issue found|issue does not exist|could not be found|not found/i.test(message);
  return {
    json: {
      fetchOk: false,
      errorCode: isNotFound ? 'JIRA_ISSUE_NOT_FOUND' : 'JIRA_UNAVAILABLE',
      httpStatus: isNotFound ? 404 : 503,
      message,
    },
  };
}
return { json: { fetchOk: true, issue: item } };

const issue = $('Classify Issue Fetch Result').first().json.issue;
const commentItems = $input.all();

function adfNodeToText(node) {
  if (!node || typeof node !== 'object') return '';
  const type = node.type;
  const content = node.content || [];
  if (type === 'text') return node.text || '';
  if (type === 'hardBreak') return '\n';
  if (type === 'rule') return '\n---\n';
  if (type === 'mention') {
    const attrs = node.attrs || {};
    return '@' + (attrs.text || attrs.id || 'mention');
  }
  if (type === 'inlineCard') {
    const attrs = node.attrs || {};
    return attrs.url || '';
  }
  if (type === 'codeBlock') {
    const inner = content.map(adfNodeToText).join('');
    return '\n```\n' + inner + '\n```\n';
  }
  if (type === 'listItem') {
    const inner = content.map(adfNodeToText).join('');
    return '- ' + inner.trim() + '\n';
  }
  if (type === 'bulletList' || type === 'orderedList') {
    return content.map(adfNodeToText).join('');
  }
  if (type === 'paragraph' || type === 'heading' || type === 'blockquote' || type === 'panel') {
    const inner = content.map(adfNodeToText).join('');
    return inner + '\n';
  }
  if (type === 'table' || type === 'tableRow' || type === 'tableCell' || type === 'tableHeader') {
    return content.map(adfNodeToText).join('');
  }
  if (type === 'doc') {
    return content.map(adfNodeToText).join('');
  }
  // Unknown node type: best-effort recurse into content rather than fail.
  return content.map(adfNodeToText).join('');
}

function adfToText(doc) {
  if (doc === null || doc === undefined) return '';
  if (typeof doc === 'string') return doc;
  if (typeof doc !== 'object') return '';
  let text = adfNodeToText(doc);
  text = text.replace(/\n{3,}/g, '\n\n');
  return text.trim();
}

const fields = issue.fields || {};
const descriptionText = adfToText(fields.description);
const comments = commentItems.map((item) => {
  const body = item.json.body;
  const bodyText = adfToText(body).trim();
  return { bodyText };
});

return {
  json: {
    key: issue.key,
    summary: fields.summary || '',
    descriptionText,
    labels: fields.labels || [],
    status: (fields.status || {}).name || '',
    issueType: (fields.issuetype || {}).name || '',
    projectKey: (fields.project || {}).key || '',
    priority: (fields.priority || {}).name || '',
    updatedAt: fields.updated || '',
    comments,
  },
};

const parsed = $json;
const MARKER_START = 'AUTOFIX_CONTEXT_V1';
const MARKER_END = 'AUTOFIX_CONTEXT_END';
const APPROVED_MARKER = '[AUTOFIX_AGENT_CONTEXT]';

const text = parsed.descriptionText || '';
const startIdx = text.indexOf(MARKER_START);
const endIdx = text.indexOf(MARKER_END);

if (startIdx === -1 || endIdx === -1 || endIdx < startIdx) {
  return {
    json: {
      ...parsed,
      contextExtracted: false,
      httpStatus: 422,
      errorCode: 'UNSUPPORTED_JIRA_CONTEXT',
      errorMessage: 'AUTOFIX_CONTEXT_V1 markers not found in description',
    },
  };
}

let jsonBlock = text.slice(startIdx + MARKER_START.length, endIdx).trim();
jsonBlock = jsonBlock.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

let autofixContext;
try {
  autofixContext = JSON.parse(jsonBlock);
} catch (e) {
  return {
    json: {
      ...parsed,
      contextExtracted: false,
      httpStatus: 422,
      errorCode: 'INVALID_AUTOFIX_CONTEXT_JSON',
      errorMessage: 'AUTOFIX_CONTEXT_V1 block is not valid JSON: ' + e.message,
    },
  };
}

const approvedAgentContext = (parsed.comments || [])
  .map((c) => c.bodyText || '')
  .filter((t) => t.startsWith(APPROVED_MARKER))
  .map((t) => t.slice(APPROVED_MARKER.length).trim())
  .filter((t) => t.length > 0);

return {
  json: {
    ...parsed,
    autofixContext,
    approvedAgentContext,
    contextExtracted: true,
  },
};

const ctx = $json;
const request = $('Validate Request').first().json;
const autofixContext = ctx.autofixContext || {};

const ALLOWED_SERVICES = ['autofix-demo-service'];
const ALLOWED_ENVIRONMENTS = ['local'];
const ALLOWED_EXCEPTION_TYPES = ['java.lang.NullPointerException'];
const ALLOWED_REQUEST_PATHS = ['/api/customers/200/display-name'];
const CLOSED_STATUSES = ['Done', 'Closed', 'Cancelled'];
const REQUIRED_LABELS = ['auto-generated', 'autofix-candidate'];

const reasons = [];

if (ctx.key !== request.jiraKey) reasons.push('ticket key mismatch: ' + ctx.key + ' != ' + request.jiraKey);
if (ctx.projectKey !== 'AUTO') reasons.push('unsupported project: ' + ctx.projectKey);
if (CLOSED_STATUSES.includes(ctx.status)) reasons.push('ticket status is closed: ' + ctx.status);

for (const label of REQUIRED_LABELS) {
  if (!(ctx.labels || []).includes(label)) reasons.push('required label missing: ' + label);
}

const fingerprintLabel = (ctx.labels || []).find((l) => l.startsWith('autofix-fp-'));
if (!fingerprintLabel) reasons.push('fingerprint label missing');

if (autofixContext.schemaVersion !== 1) reasons.push('unsupported schemaVersion: ' + autofixContext.schemaVersion);
if (String(autofixContext.incidentId) !== String(request.incidentId)) reasons.push('incidentId mismatch: ' + autofixContext.incidentId + ' != ' + request.incidentId);
if (autofixContext.fingerprint !== request.fingerprint) reasons.push('fingerprint mismatch: context has ' + autofixContext.fingerprint);
if (fingerprintLabel && fingerprintLabel !== ('autofix-fp-' + request.fingerprint)) reasons.push('fingerprint label mismatch: ' + fingerprintLabel);

if (!ALLOWED_SERVICES.includes(autofixContext.service)) reasons.push('unsupported service: ' + autofixContext.service);
if (!ALLOWED_ENVIRONMENTS.includes(autofixContext.environment)) reasons.push('unsupported environment: ' + autofixContext.environment);
if (!ALLOWED_EXCEPTION_TYPES.includes(autofixContext.exceptionType)) reasons.push('unsupported exceptionType: ' + autofixContext.exceptionType);
if (!ALLOWED_REQUEST_PATHS.includes(autofixContext.requestPath)) reasons.push('unsupported requestPath: ' + autofixContext.requestPath);
if (!autofixContext.stackTrace) reasons.push('stackTrace is empty');

if (request.branchName !== ('autofix/' + request.jiraKey)) reasons.push('branchName does not match autofix/<jiraKey>');

return {
  json: {
    ...ctx,
    contextValid: reasons.length === 0,
    validationReasons: reasons,
  },
};

const ctx = $json;
const autofixContext = ctx.autofixContext || {};
const request = $('Validate Request').first().json;

function truncate(str, max) {
  const s = String(str === undefined || str === null ? '' : str);
  return s.length > max ? s.slice(0, max) + '...[truncated]' : s;
}
function stripControlChars(str) {
  return String(str === undefined || str === null ? '' : str).replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '');
}
function normalizeText(str, max) {
  const s = stripControlChars(str).replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  return truncate(s, max);
}

const summary = normalizeText(ctx.summary, 300);
const normalizedMessage = normalizeText(autofixContext.normalizedMessage, 2000);
const applicationFrame = normalizeText(autofixContext.applicationFrame, 1000);
const stackTrace = normalizeText(autofixContext.stackTrace, 12000);

let approvedAgentContext = (ctx.approvedAgentContext || []).map((c) => normalizeText(c, 2000));
let totalLen = 0;
const cappedComments = [];
for (const c of approvedAgentContext) {
  if (totalLen + c.length > 6000) break;
  cappedComments.push(c);
  totalLen += c.length;
}
approvedAgentContext = cappedComments;

const responseBody = {
  schemaVersion: 1,
  source: 'JIRA_VIA_N8N',
  fetchedAt: new Date().toISOString(),
  ticket: {
    key: ctx.key,
    summary,
    projectKey: ctx.projectKey,
    issueType: ctx.issueType,
    status: ctx.status,
    priority: ctx.priority,
    updatedAt: ctx.updatedAt,
    labels: ctx.labels,
  },
  incident: {
    incidentId: request.incidentId,
    fingerprint: request.fingerprint,
    service: autofixContext.service,
    environment: autofixContext.environment,
    exceptionType: autofixContext.exceptionType,
    normalizedMessage,
    applicationFrame,
    httpMethod: autofixContext.httpMethod,
    requestPath: autofixContext.requestPath,
    occurrenceCount: autofixContext.occurrenceCount,
    firstSeenAt: autofixContext.firstSeenAt,
    lastSeenAt: autofixContext.lastSeenAt,
    sampleCorrelationId: autofixContext.sampleCorrelationId,
    stackTrace,
  },
  approvedAgentContext,
};

const hashInput = [
  ctx.key,
  summary,
  request.fingerprint,
  autofixContext.service,
  autofixContext.environment,
  autofixContext.exceptionType,
  normalizedMessage,
  applicationFrame,
  autofixContext.httpMethod,
  autofixContext.requestPath,
  stackTrace,
  approvedAgentContext.join('\n'),
  ctx.updatedAt,
].join('|');

return {
  json: {
    responseBody,
    hashInput,
  },
};

const item = $json;
const responseBody = { ...item.responseBody, contextHash: item.contextHash };
return { json: responseBody };
